package com.rapidresolve;
import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*;
@WebServlet("/view-problems") public class ViewProblemsServlet extends HttpServlet { protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{HttpSession h=r.getSession(false);if(h==null||h.getAttribute("userId")==null){s.sendRedirect("login.html");return;}List<Map<String,Object>> list=new ArrayList<>();String sql="SELECT * FROM problems WHERE user_id=? ORDER BY updated_at DESC";try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement(sql)){q.setInt(1,(Integer)h.getAttribute("userId"));ResultSet x=q.executeQuery();while(x.next()){Map<String,Object> m=new HashMap<>();m.put("id",x.getInt("id"));m.put("title",x.getString("title"));m.put("category",x.getString("category"));m.put("location",x.getString("location"));m.put("description",x.getString("description"));m.put("priority",x.getString("priority"));m.put("status",x.getString("status"));m.put("remark",x.getString("admin_remark"));m.put("updated",x.getTimestamp("updated_at"));list.add(m);}}catch(Exception e){throw new ServletException(e);}r.setAttribute("problems",list);r.getRequestDispatcher("view-problems.jsp").forward(r,s);}}
